def create_time_entry(workspace_id, user_id, project_id=None, description=None, start_time=None, end_time=None, billable=None, tags=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-time-entry"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(26))}"

    def _log(status, error_code=None, credential_id=None):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_ulid_like("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(),
        }
        if error_code is None:
            row.pop("error_code", None)
        logs.append(row)
        _save("usage_logs.json", logs)

    # ---- rate limit (observable dynamics) ----
    logs = _load("usage_logs.json")
    if not isinstance(logs, list):
        logs = []
    one_min_ago = _now_utc() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= one_min_ago:
                recent += 1
    if recent >= 120:
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or re.match(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id) is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a valid Clockify workspace ULID.", field="workspace_id")

    if not isinstance(user_id, str) or re.match(r"^clk_usr_[0-9A-HJKMNP-TV-Z]{26}$", user_id) is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a valid Clockify-linked user ULID.", field="user_id")

    if project_id is not None:
        if (not isinstance(project_id, str)) or re.match(r"^clk_prj_[0-9A-HJKMNP-TV-Z]{26}$", project_id) is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must be a valid project ULID.", field="project_id")

    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    def _parse_rfc3339(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339/ISO-8601 timestamp.", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    # start_time and end_time required by parameter schema
    st, e = _parse_rfc3339(start_time, "start_time")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    et, e = _parse_rfc3339(end_time, "end_time")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e

    if et < st:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be after or equal to start_time (business rule: end_time >= start_time).", field="end_time")

    if billable is not None and not isinstance(billable, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "billable must be a boolean.", field="billable")

    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")
    if len(tags) > 50:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tags must contain at most 50 items.", field="tags")

    # ---- load referenced rows and enforce business rules ----
    users = _load("clockify_users.json")
    users = users if isinstance(users, list) else []
    user_row = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if user_row is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "User not found.", user_id=user_id)
    if user_row.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is not active for this integration.", user_id=user_id)

    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    workspace_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if workspace_row is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if workspace_row.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create a time entry in an archived workspace.", workspace_id=workspace_id)

    memberships = _load("workspace_memberships.json")
    memberships = memberships if isinstance(memberships, list) else []
    mem = next(
        (m for m in memberships
         if isinstance(m, dict)
         and m.get("user_id") == user_id
         and m.get("workspace_id") == workspace_id
         and m.get("status") == "active"),
        None
    )
    if mem is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User does not have an active membership for the workspace (business rule: create-time-entry requires active membership).", user_id=user_id, workspace_id=workspace_id)

    project_row = None
    if project_id is not None:
        projects = _load("projects.json")
        projects = projects if isinstance(projects, list) else []
        project_row = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if project_row is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found.", project_id=project_id)
        if project_row.get("workspace_id") != workspace_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Project must belong to the same workspace as the time entry (business rule: projects.workspace_id = time_entries.workspace_id).", field="project_id")
        if project_row.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot associate an archived project to a new time entry.", project_id=project_id)

    # default billable if omitted
    if billable is None:
        if project_row is not None and isinstance(project_row.get("billable_default"), bool):
            billable = project_row.get("billable_default")
        else:
            billable = False

    # ---- mutation: insert pending row, then set created/failed ----
    entries = _load("time_entries.json")
    entries = entries if isinstance(entries, list) else []

    te_id = _gen_ulid_like("clk_te")
    while any(isinstance(e, dict) and e.get("id") == te_id for e in entries):
        te_id = _gen_ulid_like("clk_te")

    created_at = _iso()
    pending_row = {
        "id": te_id,
        "clockify_time_entry_id": None,
        "workspace_id": workspace_id,
        "user_id": user_id,
        "project_id": project_id,
        "description": description,
        "start_time": st.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "end_time": et.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "billable": billable,
        "tags": tags,
        "status": "pending",
        "error_message": None,
        "created_via": "mcp_tool",
        "created_at": created_at,
        "updated_at": created_at,
    }
    entries.append(pending_row)
    _save("time_entries.json", entries)

    # simulate upstream success (and enforce uniqueness for non-null clockify_time_entry_id)
    # In a real backend this would be based on upstream call result; here we deterministically succeed.
    clockify_id = _gen_ulid_like("cft")  # not constrained by pattern in schema, only uniqueness when not null
    existing_clockify_ids = set(
        e.get("clockify_time_entry_id") for e in entries
        if isinstance(e, dict) and e.get("clockify_time_entry_id") is not None
    )
    while clockify_id in existing_clockify_ids:
        clockify_id = _gen_ulid_like("cft")

    # apply lifecycle transition pending -> created
    pending_row["status"] = "created"
    pending_row["clockify_time_entry_id"] = clockify_id
    pending_row["updated_at"] = _iso()
    _save("time_entries.json", entries)

    _log("ok")
    return {"time_entry": pending_row}

def get_projects(workspace_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-projects"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(26))}"

    def _log(ok, error_code=None):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": None,
            "status": "ok" if ok else "error",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("usage_logs.json", logs)

    # rate limit: 240/min
    logs = _load("usage_logs.json")
    if not isinstance(logs, list):
        logs = []
    one_min_ago = _now_utc() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= one_min_ago:
                recent += 1
    if recent >= 240:
        _log(False, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or re.match(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id) is None:
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a valid Clockify workspace ULID.", field="workspace_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # cursor decoding: base64("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        if not raw.startswith("offset:"):
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        try:
            offset = int(raw.split(":", 1)[1])
        except ValueError:
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        if offset < 0:
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    # ---- enforce business rule: active user must have active membership to workspace ----
    users = _load("clockify_users.json")
    users = users if isinstance(users, list) else []
    active_user = next((u for u in users if isinstance(u, dict) and u.get("status") == "active"), None)
    if active_user is None:
        _log(False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active user configured for this integration.")

    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if wsp is None:
        _log(False, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    memberships = _load("workspace_memberships.json")
    memberships = memberships if isinstance(memberships, list) else []
    mem = next(
        (m for m in memberships
         if isinstance(m, dict)
         and m.get("user_id") == active_user.get("id")
         and m.get("workspace_id") == workspace_id
         and m.get("status") == "active"),
        None
    )
    if mem is None or wsp.get("status") != "active":
        _log(False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller does not have access to this workspace (requires active membership and active workspace).", workspace_id=workspace_id)

    projects = _load("projects.json")
    projects = projects if isinstance(projects, list) else []
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") != workspace_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if status is None and p.get("status") != "active":
            continue
        rows.append(p)

    rows.sort(key=lambda x: (str(x.get("name") or ""), str(x.get("id") or "")))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log(True)
    return {
        "projects": [{"id": p.get("id"), "name": p.get("name")} for p in page],
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def get_current_user(**_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-current-user"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(26))}"

    def _load_logs_file():
        candidates = [
            "usage_logs.json",
            "request_logs.json",
            "requests.json",
            "audit_logs.json",
            "audit_log.json",
            "api_usage.json",
            "usage.json",
            "clockify_request_logs.json",
        ]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _parse_ts(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _rate_limit_and_quota_check():
        fn = _load_logs_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        cutoff_60 = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        recent_60 = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= cutoff_60:
                recent_60 += 1
            if dt >= cutoff_day:
                recent_day += 1
        # Rate limit 300/min, quota 10k/day (as per tool description)
        if recent_60 >= 300:
            logs.append({"id": _gen_id("req"), "endpoint": endpoint, "timestamp": _iso(), "status": "error", "error_code": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000)})
            _save(fn, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if recent_day >= 10000:
            logs.append({"id": _gen_id("req"), "endpoint": endpoint, "timestamp": _iso(), "status": "error", "error_code": "QUOTA_EXCEEDED", "latency_ms": int((time.time() - t0) * 1000)})
            _save(fn, logs)
            return _err("QUOTA_EXCEEDED", "Read quota exceeded.")
        return None

    def _log_ok_or_error(ok, error_code=None):
        fn = _load_logs_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _iso(),
            "status": "ok" if ok else "error",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(fn, logs)

    lim = _rate_limit_and_quota_check()
    if lim:
        return lim

    users = _load("clockify_users.json")
    if not isinstance(users, list):
        users = []

    active = [u for u in users if isinstance(u, dict) and u.get("status") == "active"]
    if len(active) == 1:
        u = active[0]
        _log_ok_or_error(True)
        return {"user": {"id": u.get("id"), "clockify_user_id": u.get("clockify_user_id"), "display_name": u.get("display_name"), "email": u.get("email"), "timezone": u.get("timezone"), "status": u.get("status")}}
    if len(active) > 1:
        # Fix defect: do NOT treat multiple active users as ambiguous auth; choose a usable one.
        # Preference: one that has at least one active workspace membership to an active workspace.
        mems = _load("workspace_memberships.json")
        mems = mems if isinstance(mems, list) else []
        wsps = _load("workspaces.json")
        wsps = wsps if isinstance(wsps, list) else []
        active_wsp_ids = {w.get("id") for w in wsps if isinstance(w, dict) and w.get("status") == "active"}
        candidate_ids = set()
        for m in mems:
            if not isinstance(m, dict):
                continue
            if m.get("status") == "active" and m.get("workspace_id") in active_wsp_ids and isinstance(m.get("user_id"), str):
                candidate_ids.add(m.get("user_id"))
        preferred = next((u for u in active if u.get("id") in candidate_ids), None)
        u = preferred if preferred is not None else active[0]
        _log_ok_or_error(True)
        return {"user": {"id": u.get("id"), "clockify_user_id": u.get("clockify_user_id"), "display_name": u.get("display_name"), "email": u.get("email"), "timezone": u.get("timezone"), "status": u.get("status")}}

    # None active: create/sync (offline) a new active user and persist. Enforce unique(clockify_user_id).
    existing_clockify_ids = {u.get("clockify_user_id") for u in users if isinstance(u, dict) and u.get("clockify_user_id")}
    clockify_user_id = "cfu_" + "".join(random.choice("0123456789abcdef") for _ in range(24))
    while clockify_user_id in existing_clockify_ids:
        clockify_user_id = "cfu_" + "".join(random.choice("0123456789abcdef") for _ in range(24))

    now_iso = _iso()
    new_user = {
        "id": _gen_id("clk_usr"),
        "clockify_user_id": clockify_user_id,
        "display_name": "Clockify User",
        "email": None,
        "timezone": None,
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso,
        "last_synced_at": now_iso,
    }
    users.append(new_user)
    _save("clockify_users.json", users)
    _log_ok_or_error(True)
    return {"user": {"id": new_user.get("id"), "clockify_user_id": new_user.get("clockify_user_id"), "display_name": new_user.get("display_name"), "email": new_user.get("email"), "timezone": new_user.get("timezone"), "status": new_user.get("status")}}

def get_workspaces(user_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-workspaces"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _load_logs():
        candidates = ["request_logs.json", "requests.json", "usage.json", "audit_log.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn, _load(fn)
        return None, None

    def _log(status_code, error_code=None):
        fn, logs = _load_logs()
        if fn is None:
            return None
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        row = {"id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
               "endpoint": endpoint, "timestamp": now, "status": status_code, "latency_ms": latency_ms}
        if error_code:
            row["error_code"] = error_code

        # 300 req/min global if logs exist
        try:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            recent = 0
            if isinstance(logs, list):
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str):
                        dt = _parse_rfc3339(ts)
                        if dt is not None and dt.tzinfo is None:
                            dt = dt.replace(tzinfo=datetime.timezone.utc)
                        if dt is not None:
                            if dt.astimezone(datetime.timezone.utc).replace(tzinfo=None) >= cutoff:
                                recent += 1
            if recent >= 300:
                row["status"] = 429
                row["error_code"] = "RATE_LIMIT"
                logs.append(row)
                _save(fn, logs)
                return "RATE_LIMIT"
        except Exception:
            pass

        if isinstance(logs, list):
            logs.append(row)
            _save(fn, logs)
        return None

    # Validate
    if not isinstance(user_id, str) or re.match(r"^clk_usr_[0-9A-HJKMNP-TV-Z]{26}$", user_id) is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a valid Clockify user ULID.")
    if status is not None and status not in ("active", "archived"):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    users = _load("clockify_users.json")
    memberships = _load("workspace_memberships.json")
    workspaces = _load("workspaces.json")

    u = next((r for r in users if r.get("id") == user_id), None)
    if u is None:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "User not found.", resource="clockify_users", id=user_id)

    # Business rule: joined through memberships where membership active and workspace active (regardless of requested status filter? tool allows status filter)
    mems = [m for m in memberships if m.get("user_id") == user_id and m.get("status") == "active"]
    ws_ids = {m.get("workspace_id") for m in mems if isinstance(m.get("workspace_id"), str)}
    rows = [w for w in workspaces if w.get("id") in ws_ids]

    if status is None:
        rows = [w for w in rows if w.get("status") == "active"]
    else:
        rows = [w for w in rows if w.get("status") == status]

    rows.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("id") or ""))

    start = 0
    if cursor:
        try:
            start = int(base64.urlsafe_b64decode(cursor.encode("ascii") + b"===").decode("utf-8"))
            if start < 0:
                raise ValueError()
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows):
        next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("ascii").rstrip("=")

    rl = _log(200)
    if rl == "RATE_LIMIT":
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    return {
        "workspaces": [{"id": r.get("id"), "name": r.get("name")} for r in page],
        "meta": {"total": len(rows), "limit": limit, "has_more": next_cursor is not None, "next_cursor": next_cursor},
    }

def get_time_entries(workspace_id, user_id, project_id=None, status=None, from_time=None, to_time=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-time-entries"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(26))}"

    def _load_logs_file():
        candidates = [
            "usage_logs.json",
            "request_logs.json",
            "requests.json",
            "audit_logs.json",
            "audit_log.json",
            "api_usage.json",
            "usage.json",
            "clockify_request_logs.json",
        ]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "usage_logs.json"

    def _parse_ts(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(ok, error_code=None):
        fn = _load_logs_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {"id": _gen_id("req"), "endpoint": endpoint, "timestamp": _iso(), "status": "ok" if ok else "error", "latency_ms": int((time.time() - t0) * 1000)}
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(fn, logs)

    # Rate limit 240/min (mirror other list endpoints)
    fn_rl = _load_logs_file()
    logs_rl = _load(fn_rl)
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = _now_utc() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl:
        if not isinstance(r, dict) or r.get("endpoint") != endpoint:
            continue
        dt = _parse_ts(r.get("timestamp"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= 240:
        logs_rl.append({"id": _gen_id("req"), "endpoint": endpoint, "timestamp": _iso(), "status": "error", "error_code": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000)})
        _save(fn_rl, logs_rl)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(workspace_id, str) or re.match(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id) is None:
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a valid Clockify workspace ULID.", field="workspace_id")
    if not isinstance(user_id, str) or re.match(r"^clk_usr_[0-9A-HJKMNP-TV-Z]{26}$", user_id) is None:
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a valid Clockify user ULID.", field="user_id")
    if project_id is not None and (not isinstance(project_id, str) or re.match(r"^clk_prj_[0-9A-HJKMNP-TV-Z]{26}$", project_id) is None):
        _log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a valid Clockify project ULID.", field="project_id")
    if status is not None:
        if not isinstance(status, str) or status not in ("pending", "created", "failed", "cancelled"):
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: pending, created, failed, cancelled.", field="status")

    def _parse_rfc3339_opt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string.", field=field)
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339/ISO-8601 timestamp.", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    from_dt, fe = _parse_rfc3339_opt(from_time, "from_time")
    if fe:
        _log(False, "VALIDATION_ERROR")
        return fe
    to_dt, te = _parse_rfc3339_opt(to_time, "to_time")
    if te:
        _log(False, "VALIDATION_ERROR")
        return te

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        limit_n = limit

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("offset"), int) or obj.get("offset") < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        return obj["offset"], None

    def _encode_cursor(offset):
        payload = {"v": 1, "offset": offset}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset, ce = _decode_cursor(cursor)
    if ce:
        _log(False, "VALIDATION_ERROR")
        return ce

    # Access control: user must be active member of workspace
    mems = _load("workspace_memberships.json")
    mems = mems if isinstance(mems, list) else []
    if not any(isinstance(m, dict) and m.get("user_id") == user_id and m.get("workspace_id") == workspace_id and m.get("status") == "active" for m in mems):
        _log(False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is not an active member of the requested workspace.", workspace_id=workspace_id, user_id=user_id)

    # If project filter, ensure project belongs to workspace
    if project_id is not None:
        projects = _load("projects.json")
        projects = projects if isinstance(projects, list) else []
        pr = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if pr is None:
            _log(False, "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found.", project_id=project_id)
        if pr.get("workspace_id") != workspace_id:
            _log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must belong to the same workspace as workspace_id.", field="project_id")

    entries = _load("time_entries.json")
    entries = entries if isinstance(entries, list) else []

    filtered = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("user_id") != user_id:
            continue
        if project_id is not None and e.get("project_id") != project_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        if from_dt is not None or to_dt is not None:
            st_raw = e.get("start_time")
            st_dt = _parse_ts(st_raw) if isinstance(st_raw, str) else None
            if st_dt is None:
                continue
            if from_dt is not None and st_dt < from_dt:
                continue
            if to_dt is not None and st_dt >= to_dt:
                continue
        filtered.append(e)

    # Sort by start_time desc then created_at desc then id
    def _key(e):
        st = _parse_ts(e.get("start_time")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        ca = _parse_ts(e.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (-st.timestamp(), -ca.timestamp(), str(e.get("id") or ""))
    filtered.sort(key=_key)

    total = len(filtered)
    page = filtered[offset: offset + limit_n]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    _log(True)
    return {"time_entries": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def get_time_entry(time_entry_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0394000" if __import__("os").path.isdir("./environment_mix/0394000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-time-entry"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_req_id():
        # lightweight unique-ish id without extra deps
        return "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")

    def _log(status, error_code=None):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_req_id(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("usage_logs.json", logs)

    # Validate (relaxed to avoid false rejections seen in audit: accept any non-empty string id)
    if not isinstance(time_entry_id, str) or not time_entry_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_entry_id must be a non-empty string.", field="time_entry_id")

    entries = _load("time_entries.json")
    if not isinstance(entries, list):
        entries = []
    entry = next((e for e in entries if isinstance(e, dict) and e.get("id") == time_entry_id), None)
    if entry is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Time entry not found.", time_entry_id=time_entry_id)

    # Ambient auth: pick an active user context that is actually permitted (membership active for the entry workspace)
    users = _load("clockify_users.json")
    if not isinstance(users, list):
        users = []
    mems = _load("workspace_memberships.json")
    if not isinstance(mems, list):
        mems = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    wsp_id = entry.get("workspace_id")
    owner_user_id = entry.get("user_id")

    # Workspace must exist; if missing it's an internal consistency issue -> NOT_FOUND for access target
    workspace_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsp_id), None)
    if workspace_row is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace for this time entry was not found.", workspace_id=wsp_id)

    # Caller permitted if there exists an active user who either:
    # - is the owner of the entry and has active membership in the workspace, OR
    # - has active membership in the workspace (tool text: permitted to access workspace/user that owns the entry)
    active_user_ids = {u.get("id") for u in users if isinstance(u, dict) and u.get("status") == "active" and u.get("id")}
    permitted = False
    for uid in active_user_ids:
        has_active_mem = any(
            isinstance(m, dict) and m.get("status") == "active" and m.get("user_id") == uid and m.get("workspace_id") == wsp_id
            for m in mems
        )
        if not has_active_mem:
            continue
        if uid == owner_user_id or True:
            # membership grants access to workspace; allow read of entry in that workspace
            permitted = True
            break

    if not permitted:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to access this time entry.", time_entry_id=time_entry_id)

    _log("ok")
    return {"time_entry": entry}

