    mems = _load("workspace_memberships.json")
    if not isinstance(mems, list):
        mems = []
    active_user_ids = {u.get("id") for u in users if isinstance(u, dict) and u.get("status") == "active" and u.get("id")}
    wsp_id = entry.get("workspace_id")
    permitted = any(
        isinstance(m, dict)
        and m.get("status") == "active"
        and m.get("workspace_id") == wsp_id
        and m.get("user_id") in active_user_ids
        for m in mems
    )
    if not permitted:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to update time entries in this workspace.", workspace_id=wsp_id)

    # Validate project reference & workspace consistency if setting project_id (including clearing to None)
    if project_id is not None:
        if project_id is None:
            pass
        else:
            projects = _load("projects.json")
            if not isinstance(projects, list):
                projects = []
            prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
            if prj is None:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Project not found.", project_id=project_id)
            if prj.get("workspace_id") != wsp_id:
                _log("error", "VALIDATION_ERROR")
                return _err(
                    "VALIDATION_ERROR",
                    "Business rule: If project_id is not null then projects.workspace_id must equal time_entries.workspace_id.",
                    field="project_id",
                )

    # Lifecycle transitions enforcement
    if status is not None:
        cur = entry.get("status")
        transitions = {
            "pending": ["created", "failed", "cancelled"],
            "created": [],
            "failed": ["pending", "cancelled"],
            "cancelled": [],
        }
        if cur not in transitions:
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current status is not a valid lifecycle state.", current_status=cur)
        if status != cur:
            if status not in transitions[cur]:
                _log("error", "INVALID_TRANSITION")
                return _err(
                    "INVALID_TRANSITION",
                    "Illegal status transition for time_entries.status.",
                    from_status=cur,
                    to_status=status,
                    allowed=transitions[cur],
                )

    # Apply updates
    changed = False
    if description is not None and description != entry.get("description"):
        entry["description"] = description
        changed = True
    if start_time is not None:
        # store as provided string to match existing store style; normalize to Z if parseable
        entry["start_time"] = _iso(st_dt) if st_dt is not None else None
        changed = True
    if end_time is not None:
        entry["end_time"] = _iso(en_dt) if en_dt is not None else None
        changed = True
    if billable is not None and billable != entry.get("billable"):
        entry["billable"] = billable
        changed = True
    if tags is not None:
        entry["tags"] = tags
        changed = True
    if project_id is not None:
        entry["project_id"] = project_id
        changed = True
    if status is not None and status != entry.get("status"):
        entry["status"] = status
        changed = True
        # when moving away from failed, clear error_message on requeue
        if status == "pending":
            entry["error_message"] = None

    if not changed:
        # No success without effect for mutations: if nothing changes, treat as conflict/no-op
        _log("error", "CONFLICT")
        return _err("CONFLICT", "No fields changed; update would have no effect.", time_entry_id=time_entry_id)

    entry["updated_at"] = _iso()
    entries[idx] = entry
    _save("time_entries.json", entries)

    _log("ok")
    return {"time_entry": entry}
